function cbCreate(opts){
  opts=opts||{};
  return { state:'CLOSED', failureThreshold:opts.failureThreshold||5, successThreshold:opts.successThreshold||2,
           timeoutMs:opts.timeoutMs||1000, failures:0, successes:0, openedAt:0 };
}
function cbAllow(cb, now){
  now = (now===undefined)?0:now;
  if(cb.state==='OPEN'){
    if(now - cb.openedAt >= cb.timeoutMs){ cb.state='HALF_OPEN'; cb.successes=0; return {state:cb.state, allow:true}; }
    return {state:cb.state, allow:false};
  }
  return {state:cb.state, allow:true};
}
function cbSuccess(cb, now){
  now=now||0;
  if(cb.state==='HALF_OPEN'){ cb.successes++; if(cb.successes>=cb.successThreshold){ cb.state='CLOSED'; cb.failures=0; cb.successes=0; } }
  else if(cb.state==='CLOSED'){ cb.failures=0; }
  return {state:cb.state, allow: cb.state!=='OPEN'};
}
function cbFailure(cb, now){
  now=now||0;
  if(cb.state==='HALF_OPEN'){ cb.state='OPEN'; cb.openedAt=now; cb.successes=0; }
  else { cb.failures++; if(cb.failures>=cb.failureThreshold){ cb.state='OPEN'; cb.openedAt=now; } }
  return {state:cb.state, allow: cb.state!=='OPEN'};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { cbCreate:cbCreate, cbAllow:cbAllow, cbSuccess:cbSuccess, cbFailure:cbFailure };
}
if (typeof window !== 'undefined') {
  window.BreakerForgePure = { cbCreate:cbCreate, cbAllow:cbAllow, cbSuccess:cbSuccess, cbFailure:cbFailure };
}
